// Generated by Claude Code
package ui;

import grading.session.GradingSession;
import java.util.List;
import javafx.scene.control.Button;

/**
 * The six buttons of the grading workflow: import testers, import submissions, run, import the score sheet,
 * save the filled sheet and save the reports. Each is enabled only when its step can be done, and the next
 * step is the teal primary button.
 */
final class WorkflowButtons {

    private static final String PRIMARY = "primary";

    /**
     * Where the marker is in the workflow.
     *
     * @param busy             an import, save or grading run is going on
     * @param started          the session started; false when its work folder could not be created
     * @param testersReady     valid tester files are loaded
     * @param submissionsReady submissions are loaded
     * @param hasResults       a grading run has finished
     * @param hasSheet         a score sheet is imported
     * @param hasReports       the latest run wrote its reports
     */
    record State(boolean busy, boolean started, boolean testersReady, boolean submissionsReady,
            boolean hasResults, boolean hasSheet, boolean hasReports) {

        /** The state of {@code session}, which is null when it could not be started. */
        static State of(GradingSession session, boolean busy, boolean hasSheet) {
            if (session == null) {
                return new State(busy, false, false, false, false, hasSheet, false);
            }
            return new State(busy, true, session.testersReady(), session.submissionsReady(), session.hasResults(),
                    hasSheet, session.reportsFolder().isPresent());
        }

        /** Whether grading can start once nothing else is running. */
        boolean inputsReady() {
            return started && testersReady && submissionsReady;
        }
    }

    private final Button testerImport;
    private final Button submissionImport;
    private final Button runGrading;
    private final Button scoreSheetImport;
    private final Button writeScores;
    private final Button saveReports;

    WorkflowButtons(Button testerImport, Button submissionImport, Button runGrading, Button scoreSheetImport,
            Button writeScores, Button saveReports) {
        this.testerImport = testerImport;
        this.submissionImport = submissionImport;
        this.runGrading = runGrading;
        this.scoreSheetImport = scoreSheetImport;
        this.writeScores = writeScores;
        this.saveReports = saveReports;
    }

    void update(State state) {
        testerImport.setDisable(state.busy() || !state.started());
        submissionImport.setDisable(state.busy() || !state.started());
        runGrading.setDisable(state.busy() || !state.inputsReady());
        scoreSheetImport.setDisable(state.busy());
        writeScores.setDisable(state.busy() || !state.hasResults() || !state.hasSheet());
        saveReports.setDisable(state.busy() || !state.hasReports());
        markPrimary(state);
    }

    // Once graded, Save reports stays teal too: the reports are the run's other output.
    private void markPrimary(State state) {
        List.of(testerImport, submissionImport, runGrading, scoreSheetImport, writeScores, saveReports)
                .forEach(button -> button.getStyleClass().remove(PRIMARY));
        nextStep(state).getStyleClass().add(PRIMARY);
        if (state.hasResults()) {
            saveReports.getStyleClass().add(PRIMARY);
        }
    }

    private Button nextStep(State state) {
        if (!state.started() || !state.testersReady()) {
            return testerImport;
        } else if (!state.submissionsReady()) {
            return submissionImport;
        } else if (!state.hasResults()) {
            return runGrading;
        }
        return state.hasSheet() ? writeScores : scoreSheetImport;
    }
}
